// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "A Riot of Color".

The various colours are created using several interwoven layers of noise.
Then, as if using a fine brush, highlights are added. The animation
intensifies the flood-of-colour effect!

What other purpose could the invention of shaders by the Juju of the GPU
have served, if not for something like this?

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Forward / Backward in time

*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader, wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2960706/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, .05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define T (time+wheel.y/1e3)
#define S smoothstep
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
// white noise
float rnd(vec2 a) {
	vec3 p=fract(vec3(a.xyx)*.1031);
	p+=dot(p,p.yzx+33.33);
	return fract((p.x+p.y)*p.z);
}
// value noise
float noise(vec2 p) {
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// animates the scene
void anim(inout vec2 uv) {
  float t=T*.05;
  uv*=1.+S(.0,1.,clamp(1.2*dot(uv,uv),.0,1.));
  uv*=rot(t);
  uv.x-=12.*cos(t);	
  uv.y+=10.*sin(t);
  uv*=2.;
}
// aggregates layers of colorful noise
vec3 pattern(vec2 uv) {
	const float k=4.;
	float grain=mix(.0,noise(vec2(uv.x,fract(uv.y))*100.),min(T*.3,1.));
	vec3 col=vec3(0);
	vec2
	a=vec2(noise(uv-T+noise(uv*2.+grain)),noise(T*.1-uv+vec2(3,5))),
	b=vec2(noise(T+uv+vec2(7,3)+a*k),noise(T*.3-uv+a*k)),
	c=vec2(noise(T*.2-uv+vec2(1,4)+b*k),noise(T*.5-uv-vec2(4,1)+b*k)),
	d=vec2(noise(T*.4-uv+vec2(2,3)+c*k),noise(T*.2-uv-vec2(7,2)+c*k));
	col+=max(.3,noise(uv-d));
	col=clamp(col,.0,.35);
	float f=clamp(dot(a,b),-1.,1.);
	// add color
	col+=vec3(a.x/3.+a.y/2.+f*1.4,a.x+a.x/(2.4+f*f),b.x*b.y/1.5+f*.6+d.y*.4)/3.;
	// add highlights
	col+=pow(d.x*d.y,4.)*vec3(.2,.8,1);
	// highlight larger patches
	col+=.4*pow(a.x,5.);
	return col;
}
// puts it all together
vec3 render(vec2 uv) {
	anim(uv);
	vec3 col=pattern(uv);
	col=S(.1,1.,col);
	// brighten the scene
	col+=abs(col)*.25;
	// color grading
	col=tanh(col*col*col);
	return col;
}
void main() {
  vec3 col=render((FC-.5*R)/MN);
	// vignette
	vec2 c=FC/R;
	c*=1.-c.yx;
	float v=c.x*c.y*25.;
	col*=pow(v,.125); // very subtle
	O=vec4(col,1);
}

